25px}.drawer-open{overflow-y:hidden}.drawer-top{display:flex;justify-content:space-between;align-items:center;padding:16px 18px;border-bottom:1px solid var(--line)}.drawer-top h2{font-size:20px;font-weight:700;letter-spacing:-.5px}.drawer-close{display:grid;place-items:center;width:32px;height:32px;border:0;border-radius:50%;background:var(--bg);font-size:25px;line-height:1}.drawer-search{padding:16px 18px;background:var(--paper)}.drawer-search form{display:flex;gap:7px}.drawer-search input{width:100%;min-width:0;background:var(--bg);border:1px solid var(--line);border-radius:6px;padding:12px;font-size:13px;color:var(--ink)}.drawer-search button{width:45px;flex-shrink:0;border:0;background:var(--accent);color:#fff;border-radius:5px}.drawer-heading{background:var(--bg);border-block:1px solid var(--line);font-size:16px;font-weight:700;padding:16px 18px;letter-spacing:-.25px}.drawer-actions a{display:flex;align-items:center;gap:14px;padding:18px;border-bottom:1px solid var(--line);font-size:14px;font-weight:500}.drawer-actions a>span{margin-left:auto;font-size:23px;color:var(--muted);line-height:1}.drawer-actions svg{width:21px;height:21px;flex-shrink:0}.drawer-actions a:hover,.drawer-links a:hover{background:var(--bg);color:var(--accent)}.drawer-links{display:grid;grid-template-columns:1fr 1fr;gap:0;padding:10px 8px 15px}.drawer-links a{display:flex;justify-content:space-between;align-items:center;padding:12px 10px;border-radius:5px;font-size:14px;font-weight:500;gap:8px}.drawer-links a:after{content:'\203A';color:var(--muted);font-size:20px;line-height:1}.drawer-follow{padding:18px}.drawer-follow .btn{width:100%;padding:12px}.menu-drawer .brand{font-size:24px}.menu-drawer:focus{outline:none}.menu-open .main-nav{display:none}
